api_examples:
Example 1: simple unmarshal into typed struct:

ctx := context.Background()
var resp io.Reader = httpResponse.Body
user, err := decode.UnmarshalInto[User](ctx, resp)
if err != nil { /* handle */ }

Example 2: stream decoder usage:

ctx, cancel := context.WithCancel(context.Background())
itemsCh, errCh, cancelStream := decode.StreamDecoder[Event](ctx, stream.Body)
for {
  select {
  case e, ok := <-itemsCh:
    if !ok { return }
    handleEvent(e)
  case err := <-errCh:
    if err != nil { log.Error(err); cancelStream(); return }
  case <-ctx.Done():
    cancelStream(); return
  }
}
